/**
 * `Env` is fully generated by `wrangler types` (worker-configuration.d.ts) —
 * do not hand-declare bindings or secrets here. Secrets (POLICY_AUD,
 * DISCORD_WEBHOOK_URL, ...) appear on the generated type because `wrangler
 * types` reads them from `.dev.vars`; CI copies `.dev.vars.example` into
 * place before typechecking. To add a secret: add it to `.dev.vars` and
 * `.dev.vars.example`, then rerun `pnpm typecheck`.
 */
export type Env = Cloudflare.Env;
